1	import { NextRequest, NextResponse } from "next/server";
2	import { db } from "@/lib/db";
3	import { currentUser } from "@/lib/auth";
4	import { getGuestDiskUsage, pve, node as defaultNode, pveFor } from "@/lib/proxmox";
5	import { effectiveDiskGB } from "@/lib/extra-disk";
6	import { NO_STORE_HEADERS } from "@/app/api/_lib/no-store";
7	
8	export const dynamic = "force-dynamic";
9	
10	type Pt = { time: number; disk: number | null; maxdisk: number | null };
11	
12	// Chart timeframe → lookback window (ms). Matches DiskUsageChart's 24h/7d/30d.
13	const WINDOW_MS: Record<string, number> = {
14	  day: 24 * 60 * 60_000,
15	  week: 7 * 24 * 60 * 60_000,
16	  month: 30 * 24 * 60 * 60_000,
17	};
18	
19	/**
20	 * Real in-guest disk usage for a server the current user owns.
21	 *
22	 * Data comes from ServerDiskSample (collected by the worker via the QEMU guest
23	 * agent, since Proxmox RRD reports disk=0 for QEMU VMs) for the requested
24	 * window, plus a fresh live get-fsinfo reading appended as the current point.
25	 * Falls back to the latest stored sample when the live call isn't ready, and to
26	 * an empty series (chart shows the "not reporting" note) only when neither the
27	 * agent nor any sample yields anything.
28	 */
29	export async function GET(req: NextRequest, ctx: { params: Promise<{ id: string }> }) {
30	  const { id } = await ctx.params;
31	  const user = await currentUser();
32	  if (!user) {
33	    return NextResponse.json({ error: "unauthorized" }, { status: 401, headers: NO_STORE_HEADERS });
34	  }
35	
36	  const tf = req.nextUrl.searchParams.get("tf") ?? "day";
37	
38	  const server = await db.server.findUnique({
39	    where: { id },
40	    include: { node: true, plan: true },
41	  });
42	  if (!server || (server.userId !== user.id && user.role !== "ADMIN") || !server.vmid) {
43	    return NextResponse.json({ error: "not found" }, { status: 404, headers: NO_STORE_HEADERS });
44	  }
45	
46	  // Effective disk (plan + purchased extra) — a server that bought extra storage
47	  // must not be charted against its plan's smaller allowance.
48	  const planTotalBytes = effectiveDiskGB(server.plan.diskGB, server.extraDiskGB) * 1024 ** 3;
49	  const since = new Date(Date.now() - (WINDOW_MS[tf] ?? WINDOW_MS.day));
50	
51	  // 1. Stored history for the window.
52	  let samples: { ts: Date; usedBytes: bigint; totalBytes: bigint }[] = [];
53	  try {
54	    samples = await db.serverDiskSample.findMany({
55	      where: { serverId: id, ts: { gte: since } },
56	      orderBy: { ts: "asc" },
57	      select: { ts: true, usedBytes: true, totalBytes: true },
58	    });
59	  } catch {
60	    samples = [];
61	  }
62	
63	  const data: Pt[] = samples.map((s) => ({
64	    time: Math.floor(s.ts.getTime() / 1000),
65	    disk: Number(s.usedBytes),
66	    maxdisk: Number(s.totalBytes),
67	  }));
68	
69	  // 2. Fresh live reading for the current point (best-effort).
70	  let current: { usedBytes: number; totalBytes: number } | null = null;
71	  try {
72	    const client = server.node
73	      ? pveFor({
74	          apiUrl: server.node.apiUrl,
75	          pveNode: server.node.pveNode,
76	          tokenId: server.node.tokenId,
77	          tokenSecret: server.node.tokenSecret,
78	        })
79	      : pve;
80	    const pnode = server.node?.pveNode ?? defaultNode;
81	    current = await getGuestDiskUsage(client, pnode, server.vmid, planTotalBytes);
82	  } catch {
83	    current = null;
84	  }
85	
86	  // Fall back to the newest stored sample when the live call isn't ready.
87	  if (!current && samples.length > 0) {
88	    const last = samples[samples.length - 1];
89	    current = { usedBytes: Number(last.usedBytes), totalBytes: Number(last.totalBytes) };
90	  }
91	
92	  // Append the current reading so the chart always shows the freshest value
93	  // (and isn't empty when there are no samples yet but the agent responds).
94	  if (current) {
95	    data.push({
96	      time: Math.floor(Date.now() / 1000),
97	      disk: current.usedBytes,
98	      maxdisk: current.totalBytes,
99	    });
100	  }
101	
102	  // Prefer the fsinfo/sample total; fall back to the plan's provisioned size.
103	  const totalBytes =
104	    current?.totalBytes ??
105	    (samples.length > 0 ? Number(samples[samples.length - 1].totalBytes) : planTotalBytes);
106	
107	  return NextResponse.json({ data, planTotalBytes: totalBytes }, { headers: NO_STORE_HEADERS });
108	}
