1	import { NextRequest, NextResponse } from "next/server";
2	import { createReadStream } from "fs";
3	import { stat } from "fs/promises";
4	import path from "path";
5	import { Readable } from "stream";
6	import { db } from "@/lib/db";
7	import { currentUser } from "@/lib/auth";
8	import { checkRateLimit } from "@/lib/rate-limit";
9	import { listBackups, backupDumpDir } from "@/lib/proxmox";
10	
11	/**
12	 * Secure customer backup download.
13	 *
14	 *   GET /api/servers/[serverId]/backups/download?volid=backup:backup/vzdump-...zst
15	 *     -> streams the vzdump archive as an attachment.
16	 *
17	 * SECURITY (the whole point of the card): a customer must only ever be able to
18	 * download a backup of a server THEY own. Two independent guards:
19	 *   1. Ownership — the server row must belong to the session user (or an admin).
20	 *   2. Tenancy of the archive — the requested volid must appear in this server's
21	 *      OWN backup listing (listBackups(vmid) is filtered by the server's vmid).
22	 *      This is the identical guard requestRestore() uses, so a guessed/forged
23	 *      volid for another tenant's vmid is rejected before any disk access.
24	 * Only after both pass do we touch the filesystem, and even then the resolved
25	 * path is confined to the backup dump dir (basename only, no traversal).
26	 *
27	 * Proxmox exposes no HTTP endpoint that streams a .vma.zst archive, so the file
28	 * is read off the host filesystem (the web app runs on the Proxmox host, same as
29	 * the platform-backups status reads).
30	 */
31	export const dynamic = "force-dynamic";
32	
33	// Only ever serve real vzdump archives — never anything else in the dump dir.
34	const ARCHIVE_RE = /^vzdump-[A-Za-z0-9._-]+\.(vma|tar)(\.(zst|gz|lzo))?$/;
35	
36	export async function GET(
37	  req: NextRequest,
38	  { params }: { params: Promise<{ id: string }> }
39	) {
40	  const { id: serverId } = await params;
41	
42	  const user = await currentUser();
43	  if (!user) return NextResponse.json({ error: "unauthorized" }, { status: 401 });
44	
45	  const rl = checkRateLimit(`backups:download:${user.id}`, { max: 20, windowMs: 60_000 });
46	  if (!rl.ok) {
47	    return NextResponse.json(
48	      { error: "too many downloads — slow down", retryAfterSec: rl.retryAfterSec },
49	      { status: 429, headers: { "Retry-After": String(rl.retryAfterSec) } }
50	    );
51	  }
52	
53	  // 1. Ownership.
54	  const server = await db.server.findUnique({
55	    where: { id: serverId },
56	    select: { id: true, userId: true, vmid: true },
57	  });
58	  if (!server || (server.userId !== user.id && user.role !== "ADMIN")) {
59	    return NextResponse.json({ error: "not found" }, { status: 404 });
60	  }
61	  if (!server.vmid) {
62	    return NextResponse.json({ error: "server has no VM yet" }, { status: 400 });
63	  }
64	
65	  const volid = req.nextUrl.searchParams.get("volid");
66	  if (!volid) return NextResponse.json({ error: "missing volid" }, { status: 400 });
67	
68	  // 2. Tenancy of the archive — must belong to THIS server's vmid.
69	  let owned: Array<{ volid: string }>;
70	  try {
71	    owned = (await listBackups(server.vmid)) as Array<{ volid: string }>;
72	  } catch {
73	    return NextResponse.json(
74	      { error: "could not verify the backup — the hypervisor is briefly unavailable" },
75	      { status: 502 }
76	    );
77	  }
78	  if (!owned.some((b) => b.volid === volid)) {
79	    return NextResponse.json({ error: "that backup was not found for this server" }, { status: 404 });
80	  }
81	
82	  // Resolve volid -> on-disk file. The basename is the only part we trust; it
83	  // must be a real vzdump archive name and cannot escape the dump dir.
84	  const filename = volid.split("/").pop() ?? "";
85	  if (!ARCHIVE_RE.test(filename)) {
86	    return NextResponse.json({ error: "unsupported backup format" }, { status: 400 });
87	  }
88	  const dumpDir = await backupDumpDir();
89	  const filePath = path.join(dumpDir, filename);
90	  if (path.dirname(path.resolve(filePath)) !== path.resolve(dumpDir)) {
91	    // Defence in depth — basename regex already forbids separators.
92	    return NextResponse.json({ error: "invalid backup path" }, { status: 400 });
93	  }
94	
95	  let size: number;
96	  try {
97	    const st = await stat(filePath);
98	    if (!st.isFile()) throw new Error("not a file");
99	    size = st.size;
100	  } catch {
101	    return NextResponse.json(
102	      { error: "backup archive is not available on the host for download" },
103	      { status: 502 }
104	    );
105	  }
106	
107	  // Stream the file rather than buffering — archives are multi-GB.
108	  const nodeStream = createReadStream(filePath);
109	  const webStream = Readable.toWeb(nodeStream) as unknown as ReadableStream<Uint8Array>;
110	
111	  return new NextResponse(webStream, {
112	    status: 200,
113	    headers: {
114	      "Content-Type": "application/octet-stream",
115	      "Content-Length": String(size),
116	      "Content-Disposition": `attachment; filename="${filename.replace(/["\\]/g, "_")}"`,
117	      "Cache-Control": "private, no-store",
118	    },
119	  });
120	}
