1	import { NextRequest, NextResponse } from "next/server";
2	import { createHash, randomUUID } from "node:crypto";
3	import { EncryptJWT } from "jose";
4	import { db } from "@/lib/db";
5	import { currentUser } from "@/lib/auth";
6	import { checkRateLimit } from "@/lib/rate-limit";
7	import { pve, node as primaryNode } from "@/lib/proxmox";
8	import { NO_STORE_HEADERS } from "@/app/api/_lib/no-store";
9	
10	export const dynamic = "force-dynamic";
11	
12	/**
13	 * In-browser VNC console — ticket issuer.
14	 *
15	 * GET /api/console/[serverId]
16	 *
17	 * Flow:
18	 *  1. Authenticate the caller (owner or admin).
19	 *  2. Ask Proxmox for a websocket VNC proxy ticket for the server's VM
20	 *     (POST .../vncproxy?websocket=1). This returns a short-lived VNC ticket +
21	 *     an ephemeral port on the Proxmox node.
22	 *  3. Package the connection target — Proxmox API base, node, vmid, port, the
23	 *     VNC ticket, and the API token needed to authenticate the websocket
24	 *     upgrade — into an ENCRYPTED (JWE / A256GCM) token, valid 60s, with a
25	 *     unique jti so the relay can enforce single use.
26	 *  4. Return only { wsPath, ticketId } to the browser. The browser NEVER sees
27	 *     the Proxmox API token or the raw VNC ticket — those live inside the JWE,
28	 *     which only the relay (sharing AUTH_SECRET) can decrypt.
29	 *
30	 * The relay (scripts/console-proxy.mjs) receives sid=<JWE> on the browser
31	 * websocket, decrypts it, opens a TLS websocket to Proxmox with the real
32	 * credentials, and pipes bytes both ways.
33	 */
34	
35	// 256-bit symmetric key for JWE, derived from the app's AUTH_SECRET.
36	// The relay derives the identical key the same way — no extra shared secret.
37	function consoleKey(): Uint8Array {
38	  const secret = process.env.AUTH_SECRET;
39	  if (!secret) throw new Error("AUTH_SECRET is not set");
40	  return new Uint8Array(createHash("sha256").update(`nxeon-console:${secret}`).digest());
41	}
42	
43	export async function GET(
44	  _req: NextRequest,
45	  { params }: { params: Promise<{ serverId: string }> }
46	) {
47	  const { serverId } = await params;
48	
49	  const user = await currentUser();
50	  if (!user) return NextResponse.json({ error: "unauthorized" }, { status: 401 });
51	
52	  // Throttle ticket minting per user (falling back to IP) BEFORE we ask
53	  // Proxmox for a vncproxy ticket — each grant spawns an ephemeral vncproxy
54	  // process, so an unthrottled loop could orphan thousands of them.
55	  // Keyed on the authenticated user id, which is always present here (the 401
56	  // above already returned for anonymous callers) — the old `user.id || ip`
57	  // fallback was dead code whose `ip` half read the first, caller-supplied hop
58	  // of X-Forwarded-For.
59	  const rl = checkRateLimit(`console:${user.id}`, { max: 10, windowMs: 60_000 });
60	  if (!rl.ok) {
61	    return NextResponse.json(
62	      { error: "too many console requests — slow down", retryAfterSec: rl.retryAfterSec },
63	      { status: 429, headers: { "Retry-After": String(rl.retryAfterSec) } }
64	    );
65	  }
66	
67	  const server = await db.server.findUnique({
68	    where: { id: serverId },
69	    include: { node: true },
70	  });
71	  if (!server || (server.userId !== user.id && user.role !== "ADMIN")) {
72	    return NextResponse.json({ error: "not found" }, { status: 404 });
73	  }
74	  if (!server.vmid) {
75	    return NextResponse.json({ error: "no VM provisioned" }, { status: 409 });
76	  }
77	  if (server.status !== "RUNNING") {
78	    return NextResponse.json(
79	      { error: "server must be running to open the console" },
80	      { status: 409 }
81	    );
82	  }
83	
84	  // Resolve which Proxmox node + credentials to use. Multi-node servers carry a
85	  // Node row; otherwise fall back to the primary node from the environment.
86	  const apiBase = server.node?.apiUrl ?? process.env.PROXMOX_API_URL ?? "https://127.0.0.1:8006";
87	  const pveNode = server.node?.pveNode ?? primaryNode;
88	  const tokenId = server.node?.tokenId ?? process.env.PROXMOX_TOKEN_ID ?? "";
89	  const tokenSecret = server.node?.tokenSecret ?? process.env.PROXMOX_TOKEN_SECRET ?? "";
90	
91	  if (!pveNode || !tokenId || !tokenSecret) {
92	    return NextResponse.json({ error: "console not configured" }, { status: 500 });
93	  }
94	
95	  // Request a websocket VNC proxy ticket from Proxmox.
96	  let vnc: { ticket: string; port: string | number };
97	  try {
98	    // Use the node-scoped client for non-primary nodes so the ticket is valid
99	    // for the right host; the primary node uses the shared `pve` client.
100	    if (server.node) {
101	      const { pveFor } = await import("@/lib/proxmox");
102	      const client = pveFor({
103	        apiUrl: server.node.apiUrl,
104	        pveNode: server.node.pveNode,
105	        tokenId: server.node.tokenId,
106	        tokenSecret: server.node.tokenSecret,
107	      });
108	      vnc = await client.post(`/nodes/${pveNode}/qemu/${server.vmid}/vncproxy`, {
109	        websocket: 1,
110	      });
111	    } else {
112	      vnc = await pve.post(`/nodes/${pveNode}/qemu/${server.vmid}/vncproxy`, {
113	        websocket: 1,
114	      });
115	    }
116	  } catch {
117	    return NextResponse.json(
118	      { error: "hypervisor did not grant a console ticket — try again shortly" },
119	      { status: 502 }
120	    );
121	  }
122	
123	  if (!vnc?.ticket || vnc.port === undefined) {
124	    return NextResponse.json({ error: "invalid console ticket from hypervisor" }, { status: 502 });
125	  }
126	
127	  const ticketId = randomUUID();
128	
129	  // Encrypt the full connection target. Only the relay can read this.
130	  const sid = await new EncryptJWT({
131	    apiBase,
132	    node: pveNode,
133	    vmid: server.vmid,
134	    port: Number(vnc.port),
135	    vncticket: vnc.ticket,
136	    tokenId,
137	    tokenSecret,
138	  })
139	    .setProtectedHeader({ alg: "dir", enc: "A256GCM" })
140	    .setJti(ticketId)
141	    .setIssuedAt()
142	    .setExpirationTime("60s")
143	    .encrypt(consoleKey());
144	
145	  // Public websocket URL of the relay. In production behind HTTPS, set
146	  // CONSOLE_PUBLIC_WS_URL to a wss:// endpoint (e.g. proxied by nginx) so the
147	  // browser isn't blocked by mixed-content. Otherwise we hand out a bare
148	  // ws://PUBLIC_IP:PORT/console URL for the standalone relay.
149	  const base =
150	    process.env.CONSOLE_PUBLIC_WS_URL?.replace(/\/+$/, "") ??
151	    `ws://${process.env.PUBLIC_IP ?? "127.0.0.1"}:${process.env.CONSOLE_PROXY_PORT ?? "8899"}/console`;
152	
153	  const wsPath = `${base}?sid=${encodeURIComponent(sid)}`;
154	
155	  // `wsPath` embeds the JWE that authorizes a VNC session on this customer's
156	  // VM. It is a GET response and carried no cache directive at all, so a shared
157	  // proxy could store it and hand a working console ticket for someone else's
158	  // server to the next caller of this URL. Never cache it anywhere.
159	  return NextResponse.json({ wsPath, ticketId }, { headers: NO_STORE_HEADERS });
160	}
