8	/**
9	 * GET /api/chat/attachment/[id]?visitorId=…  — stream a chat image ONLY to an
10	 * authorized viewer:
11	 *   • any staff member (SUPPORT / ADMIN), OR
12	 *   • the visitor who owns the conversation (visitorId query param matches), OR
13	 *   • the signed-in customer the conversation is linked to (userId matches).
14	 *
15	 * `id` is a database id, never a filename, so there is no path traversal. The
16	 * response is locked down: the real stored MIME (always an allow-listed image),
17	 * `nosniff`, an inline disposition with a fixed filename, and a `default-src
18	 * 'none'` CSP so it can never execute as a document even if a browser is coaxed
19	 * into treating it as one.
20	 */
21	
22	function clip(v: unknown, max: number): string | null {
23	  return typeof v === "string" && v.trim() ? v.trim().slice(0, max) : null;
24	}
25	
26	export async function GET(
27	  req: Request,
28	  { params }: { params: Promise<{ id: string }> }
29	) {
30	  const { id } = await params;
31	  if (typeof id !== "string" || !id) return new Response("Not found", { status: 404 });
32	
33	  const attachment = await db.chatAttachment.findUnique({
34	    where: { id },
35	    include: { message: { include: { conversation: true } } },
36	  });
37	  if (!attachment) return new Response("Not found", { status: 404 });
38	
39	  const convo = attachment.message.conversation;
40	
41	  // --- Authorization: same model as upload (participant or staff) ---
42	  let authorized = false;
43	
44	  const staff = await realUser();
45	  if (staff && isStaff(staff.role)) {
46	    authorized = true;
47	  } else {
48	    const url = new URL(req.url);
49	    const visitorId = clip(url.searchParams.get("visitorId"), 100);
50	    if (visitorId && visitorId === convo.visitorId) {
51	      authorized = true;
52	    } else if (convo.userId) {
53	      const user = await currentUser();
54	      if (user && user.id === convo.userId) authorized = true;
55	    }
56	  }
57	
58	  if (!authorized) return new Response("Forbidden", { status: 403 });
59	
60	  // Defense in depth: never serve anything that isn't an allow-listed image.
61	  const mime = isAllowedImageMime(attachment.mime) ? attachment.mime : "application/octet-stream";
62	
63	  const data: Buffer = Buffer.isBuffer(attachment.data)
64	    ? attachment.data
65	    : Buffer.from(attachment.data as Uint8Array);
66	
67	  return new Response(new Uint8Array(data), {
68	    status: 200,
69	    headers: {
70	      "Content-Type": mime,
71	      "Content-Length": String(data.length),
72	      "Content-Disposition": 'inline; filename="image"',
73	      "X-Content-Type-Options": "nosniff",
74	      "Content-Security-Policy": "default-src 'none'; sandbox",
75	      "Cache-Control": "private, max-age=86400, no-transform",
76	    },
77	  });
78	}
