117	  userInput: string
118	): Promise<CreateResult> {
119	  try {
120	    const { user, server } = await ownedServer(serverId);
121	    const limited = throttle(user.id, "create", 10);
122	    if (limited) return { ok: false, error: limited };
123	    if (server.status !== "RUNNING") return { ok: false, error: "The server must be running to create a database." };
124	    if (await lifecycleBusy(server.id))
125	      return { ok: false, error: "Another server operation is in progress — try again shortly." };
126	
127	    if (!(DB_ENGINES as readonly string[]).includes(engine))
128	      return { ok: false, error: "Choose a supported database engine." };
129	    const name = String(nameInput ?? "").trim();
130	    const dbUser = String(userInput ?? "").trim();
131	    if (!IDENT_RE.test(name))
132	      return { ok: false, error: "Database name: 1–32 letters, digits or underscores." };
133	    if (!IDENT_RE.test(dbUser))
134	      return { ok: false, error: "User name: 1–32 letters, digits or underscores." };
135	
