153	/**
154	 * Request a one-click Let's Encrypt certificate for `domain` on one of the
155	 * caller's servers. Validates the domain, checks server ownership, applies the
156	 * shared rate-limit guard, creates a PENDING SslCertificate row and enqueues an
157	 * SSL_ISSUE job.
158	 */
159	export async function requestCertificate(
160	  serverId: string,
161	  domain: string
162	): Promise<{ error?: string; id?: string }> {
163	  let ctx;
164	  try {
165	    ctx = await ownedServer(serverId);
166	  } catch (e: any) {
167	    return { error: e.message };
168	  }
169	  const { user, server } = ctx;
170	
171	  const clean = String(domain ?? "").toLowerCase().trim().replace(/\.$/, "");
172	  if (!FQDN_RE.test(clean)) {
173	    return { error: "Enter a valid domain name (e.g. app.example.com) — no protocol, port or wildcard." };
174	  }
175	
176	  // One active/in-flight cert per (user, domain): don't let a customer stack
177	  // duplicate issue jobs for the same hostname.
178	  const existing = await db.sslCertificate.findFirst({
179	    where: { userId: user.id, domain: clean, status: { in: ["PENDING", "ISSUING", "ACTIVE"] } },
180	  });
181	  if (existing) {
182	    return {
183	      error:
184	        existing.status === "ACTIVE"
185	          ? `You already have an active certificate for ${clean}.`
186	          : `A certificate for ${clean} is already being issued.`,
187	    };
188	  }
189	
190	  // The duplicate check above is defeated by delete-and-retry, so the weekly
191	  // rate-limit guard is the thing that actually stops a retry loop from burning
192	  // Let's Encrypt's limit.
193	  const rate = await issueAttemptsFor(clean);
194	  if (rateLimited(rate)) return { error: rateLimitMessage(clean, rate) };
195	
196	  // One in-flight job per server — the platform's own invariant, which
197	  // `renewCertificate` below already honours and this path did not. It matters
198	  // more here than there: certbot needs the box in a steady state, so an
199	  // SSL_ISSUE queued behind a REINSTALL or a RESIZE runs against a machine that
200	  // is being wiped or resized underneath it. That attempt fails, and it still
201	  // consumes one of the customer's five weekly Let's Encrypt slots.
202	  const busy = await db.job.count({
203	    where: { serverId: server.id, status: { in: ["QUEUED", "RUNNING"] } },
204	  });
205	  if (busy > 0) {
206	    return {
207	      error:
208	        "Another operation is already queued for this server. The platform runs one job at a time, and a " +
209	        "certificate issued mid-rebuild would fail and burn one of your weekly Let's Encrypt attempts — " +
210	        "try again once the current job finishes.",
211	    };
212	  }
213	
214	  const cert = await db.sslCertificate.create({
215	    data: {
216	      userId: user.id,
217	      serverId: server.id,
218	      domain: clean,
219	      status: "PENDING",
220	      issuer: "letsencrypt",
221	    },
222	  });
223	  await db.job.create({
224	    // `domain` is carried in the payload because the rate-limit counter above
225	    // keys on the hostname and must survive the certificate row being deleted.
226	    data: { type: "SSL_ISSUE", serverId: server.id, payload: { certId: cert.id, domain: clean } },
227	  });
228	  await db.auditLog.create({
229	    data: { userId: user.id, action: "ssl.request", detail: `${clean} on ${server.hostname}` },
230	  });
231	  revalidatePath("/dashboard/ssl");
232	  return { id: cert.id };
233	}
234	
235	/**
236	 * Reissue a certificate now (owner only), for an ACTIVE/EXPIRED/FAILED row.
237	 *
238	 * Shares the weekly counter with requestCertificate and the worker's renewal
239	 * sweep, so a customer hammering this button cannot exhaust Let's Encrypt's
240	 * duplicate-certificate limit.
241	 */
242	export async function renewCertificate(id: string): Promise<{ error?: string }> {
243	  let ctx;
244	  try {
245	    ctx = await ownedCertificate(id);
246	  } catch (e: any) {
247	    return { error: e.message };
248	  }
249	  const { user, cert } = ctx;
250	
251	  if (!["ACTIVE", "EXPIRED", "FAILED"].includes(cert.status)) {
252	    return { error: "This certificate is already being worked on — wait for the current attempt to finish." };
253	  }
254	  if (!cert.serverId) {
255	    return { error: "This certificate is not attached to a server, so it cannot be issued." };
256	  }
257	  if (await liveIssueJob(cert.id)) {
258	    return { error: "An issue job for this certificate is already queued." };
259	  }
260	
261	  const rate = await issueAttemptsFor(cert.domain);
262	  if (rateLimited(rate)) return { error: rateLimitMessage(cert.domain, rate) };
263	
264	  // One in-flight job per server, matching the worker's own invariant.
265	  const busy = await db.job.count({
266	    where: { serverId: cert.serverId, status: { in: ["QUEUED", "RUNNING"] } },
267	  });
268	  if (busy > 0) {
269	    return {
270	      error:
271	        "Another operation is already queued for this server. The platform runs one job at a time — try again once it finishes.",
272	    };
273	  }
274	
275	  await db.job.create({
276	    data: {
277	      type: "SSL_ISSUE",
278	      serverId: cert.serverId,
279	      // `renewal: true` keeps a still-valid certificate ACTIVE if the reissue
280	      // fails, instead of flipping a working site's row to FAILED.
281	      payload: { certId: cert.id, domain: cert.domain, renewal: true },
282	    },
283	  });
284	  await db.auditLog.create({
285	    data: { userId: user.id, action: "ssl.renew", detail: `${cert.domain}` },
286	  });
287	  revalidatePath("/dashboard/ssl");
288	  return {};
289	}
290	
291	/**
292	 * Permanently remove a certificate record (owner only).
293	 *
294	 * ISSUING is only protected while a job is genuinely running. Before
295	 * 2026-07-26 this refused every ISSUING row unconditionally, so a row stranded
296	 * by a worker restart was permanently undeletable — and because
297	 * requestCertificate rejects a new request while a PENDING/ISSUING/ACTIVE row
298	 * exists for the hostname, the customer lost the ability to get a certificate
299	 * for that domain at all, with no way to clear it themselves.
300	 */
301	export async function deleteCertificate(id: string): Promise<{ error?: string }> {
302	  let ctx;
303	  try {
304	    ctx = await ownedCertificate(id);
305	  } catch (e: any) {
306	    return { error: e.message };
307	  }
308	  const { user, cert } = ctx;
309	
310	  if (cert.status === "PENDING" || cert.status === "ISSUING") {
311	    const live = await liveIssueJob(cert.id);
312	    if (live?.status === "RUNNING") {
313	      return {
314	        error:
315	          "certbot is running for this domain right now — deleting mid-issue would leave a certificate on the " +
316	          "server with no record of it. Try again in a minute.",
317	      };
318	    }
319	    if (live) {
320	      // Queued but not started: cancel it, otherwise the worker would pick up a
321	      // job whose certificate row no longer exists and log a spurious failure.
322	      await db.job.updateMany({
323	        where: { id: live.id, status: "QUEUED" },
324	        data: {
325	          status: "FAILED",
326	          error: "Cancelled — the customer deleted the certificate request before it started.",
327	        },
328	      });
329	    }
330	  }
331	
332	  await db.sslCertificate.delete({ where: { id } });
333	  await db.auditLog.create({
334	    data: { userId: user.id, action: "ssl.delete", detail: `${cert.domain}` },
335	  });
336	  revalidatePath("/dashboard/ssl");
337	  return {};
338	}
339	
340	/**
341	 * Flip automatic renewal on/off for a certificate (owner only).
342	 *
343	 * This is no longer decoration: worker/ssl.ts's renewal sweep reads `autoRenew`
344	 * and, when it is off, reissues nothing and warns the customer before expiry
345	 * instead.
346	 */
347	export async function toggleAutoRenew(id: string): Promise<{ error?: string }> {
348	  let ctx;
349	  try {
350	    ctx = await ownedCertificate(id);
351	  } catch (e: any) {
352	    return { error: e.message };
353	  }
354	  await db.sslCertificate.update({
355	    where: { id },
356	    data: { autoRenew: !ctx.cert.autoRenew },
357	  });
358	  await db.auditLog.create({
359	    data: {
360	      userId: ctx.user.id,
361	      action: "ssl.autorenew",
362	      detail: `${ctx.cert.domain} -> ${!ctx.cert.autoRenew ? "on" : "off"}`,
363	    },
364	  });
365	  revalidatePath("/dashboard/ssl");
366	  return {};
367	}
