7	/**
8	 * TOTP verification primitives — deliberately a PLAIN module, not `"use server"`.
9	 *
10	 * SECURITY (2026-07-25): `verifyTotpForUser` used to live in `lib/actions-2fa.ts`,
11	 * which carries `"use server"` at the top. Every export of such a module is a
12	 * registered, network-callable server action. That made this function a public
13	 * endpoint taking an arbitrary `userId`, performing no authentication, no
14	 * ownership check and no rate limiting, returning a raw boolean — and mutating
15	 * state, because a matching backup code is consumed. `login()` is throttled to 10
16	 * attempts per 15 minutes per email+IP; calling this action directly bypassed that
17	 * completely, allowing unlimited TOTP and backup-code guessing against a named
18	 * account. Victim user IDs were obtainable from the team page.
19	 *
20	 * Keeping these here means they can only ever be reached by server code that
21	 * imports them (the login flow, and the 2FA management actions) — there is no
22	 * action ID for a client to call. Do NOT re-export any of this from a
23	 * `"use server"` module.
24	 */
25	
26	/** Hash a backup code for storage/comparison. Case- and whitespace-insensitive. */
27	export function hashCode(code: string): string {
28	  return createHash("sha256").update(code.trim().toLowerCase()).digest("hex");
29	}
30	
31	/**
32	 * Resolve a user's TOTP secret, preferring the encrypted column and falling back
33	 * to any legacy plaintext value so already-enrolled users keep working.
34	 */
35	export function totpSecretOf(user: {
36	  totpSecret: string | null;
37	  totpSecretEnc: string | null;
38	}): string | null {
39	  return decryptSecret(user.totpSecretEnc) ?? user.totpSecret;
40	}
41	
42	/**
43	 * How long a spent TOTP step stays remembered. A code is valid across a ±1 step
44	 * window, so the last step that can still accept a given code ends 60s after the
45	 * step it was minted for begins; 90s covers that with margin and then forgets,
46	 * which keeps the marker store bounded.
47	 */
48	const TOTP_REPLAY_TTL_MS = 90_000;
49	
50	/**
51	 * Verify a submitted code for a user: passes if it matches TOTP OR consumes a
52	 * valid one-time backup code (which is then removed).
53	 *
54	 * Callers MUST have already established that the request is entitled to attempt
55	 * a 2FA check for this user (i.e. the password stage passed) and MUST apply their
56	 * own rate limiting — this function deliberately has neither, which is precisely
57	 * why it must never be exposed as a server action.
58	 *
59	 * BOTH kinds of proof this accepts are ONE-TIME, and neither was:
60	 *
61	 *  - A TOTP code was accepted for as long as it verified, which is up to 90
62	 *    seconds across the drift window, any number of times. RFC 6238 §5.2 is
63	 *    explicit that a code must be accepted once; "you must also know the
64	 *    password" is not a substitute, because the scenario this protects against
65	 *    is precisely the one where the password is already known and the code was
66	 *    observed — a shoulder-surf, a screenshot, a code read back over the phone
67	 *    to someone claiming to be support. The step that a code belongs to is now
68	 *    claimed on first use and refused thereafter.
69	 *
70	 *  - A backup code was consumed with a read-modify-write: read the array, filter
71	 *    the used entry out, write the array back. Two requests submitting the SAME
72	 *    backup code concurrently both read it as present, both matched, and both
73	 *    returned true — one printed one-time code was worth two sign-ins. The
74	 *    removal is now a compare-and-swap: the UPDATE only applies while the code is
75	 *    still in the array, so exactly one of the racers can win it.
76	 *
77	 * A rejected replay is reported exactly like a wrong code — same `false`, no
78	 * separate signal — so this cannot be used to probe which codes have been seen.
79	 */
80	export async function verifyTotpForUser(userId: string, code: string): Promise<boolean> {
81	  const user = await db.user.findUnique({ where: { id: userId } });
82	  if (!user || !user.totpEnabled) return false;
83	  const secret = totpSecretOf(user);
84	  if (!secret) return false;
85	
86	  const step = matchTOTPCounter(secret, code);
87	  if (step !== null) {
88	    // Single-use: the first presentation of this step wins, later ones do not.
89	    return claimOnce(`totp:${user.id}:${step}`, TOTP_REPLAY_TTL_MS);
90	  }
91	
92	  // Fall back to consuming a backup code.
93	  const submitted = hashCode(code);
94	  if (!user.backupCodes.includes(submitted)) return false;
95	  const remaining = user.backupCodes.filter((c) => c !== submitted);
96	  // Compare-and-swap: `has` makes the code's continued presence part of the
97	  // WHERE clause, so a concurrent request that already spent it updates zero
98	  // rows and is refused. `update` (which matches on id alone) could not fail.
99	  const claimed = await db.user.updateMany({
100	    where: { id: user.id, backupCodes: { has: submitted } },
101	    data: { backupCodes: remaining },
102	  });
103	  if (claimed.count === 0) return false;
104	  await db.auditLog.create({ data: { userId: user.id, action: "user.2fa_backup_code_used" } });
105	  return true;
106	}
