82	 * No-op when the amount is 0 or the account already has signup credit.
83	 *
84	 * PRIVATE ON PURPOSE. This used to be an export of lib/actions-growth.ts — a
85	 * `"use server"` file — which made "credit an arbitrary `userId`" a public
86	 * network endpoint whose only defence was a guard that inspected request
87	 * headers. It has exactly one caller, `register` below, and a function with one
88	 * in-process caller has no business being an endpoint at all. Keeping it here,
89	 * unexported, is the same reasoning that moved `safeNext` and
90	 * `verifyTotpForUser` out of `"use server"` files.
91	 *
92	 * It also removes a live fragility: the old guard resolved the acting account
93	 * from the session, and `register` calls this immediately after minting that
94	 * session, so the grant's success depended on request-scoped session state
95	 * settling mid-action. Nothing about "did this new account already get its
96	 * welcome credit?" needs the session — `signupCreditCents` on the row is the
97	 * only fact that matters, and it is what makes the grant idempotent.
98	 */
99	async function grantSignupCredit(userId: string): Promise<number> {
100	  // Prefer the admin-editable setting (`signup_free_credit_cents`); fall back to
101	  // the legacy SIGNUP_FREE_CREDIT_CENTS env default when the setting is unset.
102	  const cents = await getSettingInt("signup_free_credit_cents", signupFreeCreditCents());
103	  if (cents <= 0) return 0;
104	  // Idempotent claim: only ever grants against a row that has no signup credit
105	  // yet, so a retry (or two concurrent registrations of the same account, which
106	  // the unique email index already prevents) cannot pay twice.
107	  const claimed = await db.user.updateMany({
108	    where: { id: userId, signupCreditCents: 0 },
109	    data: { balanceCents: { increment: cents }, signupCreditCents: cents },
110	  });
111	  if (claimed.count === 0) return 0;
112	  await db.walletTransaction.create({
113	    data: { userId, amountCents: cents, description: "Welcome credit" },
114	  });
115	  return cents;
116	}
