248	export async function login(
249	  prev: any,
250	  formData: FormData,
251	): Promise<{ error?: string; needs2fa?: boolean }> {
252	  const parsed = credsSchema.safeParse({
253	    // Same canonical form the account was stored under (lib/email-normalize.ts).
254	    // Without this, signing in as `Alice@Example.com` missed a row stored as
255	    // `alice@example.com` and reported bad credentials for a correct password.
256	    email: normalizeEmail(formData.get("email")),
257	    password: formData.get("password"),
258	  });
259	  if (!parsed.success) return { error: "Invalid email or password." };
260	
261	  // App-level throttle per email+IP over a 15 min window. The max-attempts cap is
262	  // admin-configurable (`login_ratelimit_max`, default 10) rather than hardcoded.
263	  //
264	  // The IP comes from `clientIp` (lib/rate-limit.ts), NEVER from
265	  // `x-forwarded-for.split(",")[0]`. nginx forwards the header with
266	  // `$proxy_add_x_forwarded_for`, which APPENDS the peer it saw to whatever the
267	  // client sent — so the leftmost entry is a free-text field the caller filled
268	  // in, and keying on it meant an attacker could rotate one header value per
269	  // request and never bind this limiter at all. That is the limiter standing
270	  // between a known email address and unlimited password guesses, and (below)
271	  // unlimited 2FA code guesses once a password is known. See the docblock on
272	  // `clientIp` for the measurement.
273	  const rlId = `${parsed.data.email}:${clientIp(await headers())}`;
274	  const maxAttempts = Math.max(1, await getSettingInt("login_ratelimit_max", 10));
275	  const rl = checkRateLimit(`login:${rlId}`, { max: maxAttempts, windowMs: 15 * 60 * 1000 });
276	  if (!rl.ok) return { error: `Too many attempts. Try again in ${rl.retryAfterSec}s.` };
277	
278	  const user = await db.user.findUnique({ where: { email: parsed.data.email } });
279	  // ALWAYS spend one bcrypt comparison, even when the address does not exist.
280	  //
281	  // `!user || !(await bcrypt.compare(...))` short-circuits: with no account, bcrypt
282	  // never ran. The reply text was correctly identical either way, but the reply
283	  // TIME was not — bcrypt at cost 12 is ~250ms against a single indexed SELECT, a
284	  // gap one sample per address is enough to read. That turns the login form into
285	  // an account-enumeration oracle: "does this person bank here", answered for any
286	  // address, at scale, without ever guessing a password.
287	  //
288	  // It was materially worse while the throttle above was keyed on the
289	  // caller-supplied first hop of `x-forwarded-for`, because the rate limit that
290	  // would otherwise cap sampling could itself be stepped around per request. That
291	  // is fixed, but a defence that only works because another defence works is not
292	  // one, so the timing is equalised on its own terms.
293	  //
294	  // The comparison against DUMMY_HASH is discarded — it exists solely to spend the
295	  // same ~250ms. Keep the reply string identical to the wrong-password case.
296	  const passwordOk = user
297	    ? await bcrypt.compare(parsed.data.password, user.passwordHash)
298	    : ((await bcrypt.compare(parsed.data.password, DUMMY_PASSWORD_HASH)), false);
299	  // `!user` is repeated here purely so TypeScript narrows `user` for the code
300	  // below. It is NOT a short-circuit any more: `passwordOk` above has already
301	  // spent the bcrypt comparison in both branches, which is the whole point.
302	  if (!user || !passwordOk) {
303	    return { error: "Invalid email or password." };
304	  }
305	  if (user.suspended) return { error: "This account is suspended." };
306	
307	  // Two-factor challenge, if enabled on the account.
308	  if (user.totpEnabled) {
309	    const code = String(formData.get("code") ?? "").trim();
310	    if (!code) return { error: "Enter your 2FA code to continue.", needs2fa: true };
311	    if (!(await verifyTotpForUser(user.id, code))) {
312	      return { error: "Invalid 2FA code.", needs2fa: true };
313	    }
314	  }
315	
316	  resetRateLimit(`login:${rlId}`);
317	  await audit(user.id, "user.login");
318	  await createSession(user.id);
319	  // Land where they were HEADING, not on a generic dashboard.
320	  //
321	  // Public CTAs like "Migrate free →" send a logged-out visitor into
322	  // /dashboard/..., which bounces to /login and — until now — discarded what they
323	  // clicked. They signed in and arrived somewhere unrelated, with no route back to
324	  // the thing they wanted. Seven CTAs did this, the worst being "Contact support"
325	  // on the PUBLIC help page, where a prospect met a login wall instead of /contact.
326	  //
327	  // `safeNext` only ever returns a path on THIS site (see its definition): an
328	  // open redirect on a login form is a phishing primitive, so an absolute URL, a
329	  // protocol-relative `//evil.test` or anything that is not a single-slash path is
330	  // discarded rather than sanitised.
331	  const next = safeNext(formData.get("next"));
332	  redirect(next ?? (user.role === "ADMIN" ? "/admin" : "/dashboard"));
333	}
