342	/**
343	 * Enforce the admin-configured per-user server cap (`max_servers_per_user`,
344	 * default 10; 0 = unlimited). Counts every server the user owns that isn't being
345	 * torn down (DELETING). Returns an error message when the cap is reached, else null.
346	 */
347	async function serverLimitError(userId: string): Promise<string | null> {
348	  const cap = await getSettingInt("max_servers_per_user", 10);
349	  if (cap <= 0) return null; // 0 (or negative) = unlimited
350	  const owned = await db.server.count({ where: { userId, status: { notIn: ["DELETING"] } } });
351	  if (owned >= cap) {
352	    return `You've reached your limit of ${cap} server${cap === 1 ? "" : "s"}. Delete one or contact support to raise the cap.`;
353	  }
354	  return null;
355	}
