458	  let quote;
459	  try {
460	    quote = await orderQuote(intent);
461	  } catch (e) {
462	    if (e instanceof OrderError) return { error: e.message };
463	    throw e;
464	  }
465	
466	  // Managed first-month-free eligibility. If this account/IP has ALREADY redeemed
467	  // the promo (or it's switched off), re-quote at FULL price so the wallet split,
468	  // the card leg and the stamped total are all full — the free month is a
469	  // once-per-person offer. The wallet path is self-correcting regardless (its
470	  // atomic claim inside placeOrder charges full on a lost claim), but the CARD
471	  // leg settles up front, so it MUST be priced full here or a repeat customer
472	  // gets a second discounted checkout. This mirrors the coupon guard below.
473	  // `|| null` matters: hashIp returns "" when the IP is unavailable, and an empty
474	  // string is a REAL value to the (promoId, ipHash) unique — it would collide
475	  // across every IP-less redemption and wrongly block them. NULLs are distinct.
476	  const promoIpHash = hashIp(clientIp(await headers()), process.env.AUTH_SECRET ?? "nxeon") || null;
477	  if (quote.promoCreditCents > 0 && !(await firstMonthFreeEligible(user.id, promoIpHash))) {
478	    quote = await orderQuote(intent, { suppressPromo: true });
479	  }
480	  const promoCampaign = promoCampaignFromCookie(await cookies());
481	
482	  const isAdmin = user.role === "ADMIN";
483	  const freePath = !!intent.free && isAdmin;
484	
485	  // Wallet-aware split. The customer's Review screen computes the exact same split
486	  // (lib/wallet-split.ts) from the same inputs, so what they see === what we charge.
487	  // `useWallet` defaults ON (only "0" turns it off) so existing forms keep applying
488	  // the balance. Free admin grants skip the split entirely (no money moves).
489	  const useWallet = formData.get("useWallet") !== "0";
490	  // VAT/GST for this customer (Finding 1), resolved from their billing country. The
491	  // rate is constant for the request; the tax cents track whatever net the quote
492	  // settles on after any promo/coupon re-quote below. The wallet split and the card
493	  // leg are computed from the TAX-INCLUSIVE total so the card is charged the same
494	  // total the customer is shown, and the stamped `OrderPrice` carries the tax so the
495	  // confirm route settles it without re-deriving. A free admin grant is never taxed.
496	  const taxCtx = freePath ? { ratePercent: 0, country: "", reverseCharged: false } : await taxContextForUser(user);
497	  const taxOn = (netCents: number) => Math.round((netCents * taxCtx.ratePercent) / 100);
498	  const dueWithTax = (netCents: number) => netCents + taxOn(netCents);
499	  // `let`: a first-month-free hold lost to a concurrent checkout forces a full-price
500	  // re-quote below, which changes the split. Free admin grants skip it entirely.
501	  let { walletApplied, cardCents } = freePath
502	    ? { walletApplied: 0, cardCents: 0 }
503	    : walletSplit({ dueCents: dueWithTax(quote.chargeCents), balanceCents: user.balanceCents, useWallet });
504	
505	  // Card portion is $0 (free admin grant, or the wallet fully covers the charge) →
506	  // provision straight away. placeOrder debits the FULL chargeCents from the wallet
507	  // (or nothing, for a free grant); the balance check inside it holds because a
508	  // $0 card portion means balance >= chargeCents.
509	  if (freePath || cardCents <= 0) {
510	    let serverId: string;
511	    try {
512	      // Reuse the request-scoped IP hash computed above so placeOrder can enforce
513	      // both the coupon's once-per-person guard and the first-month-free 1/IP cap.
514	      serverId = await placeOrder(user, intent, null, { ipHash: promoIpHash, campaign: promoCampaign });
515	    } catch (e) {
516	      if (e instanceof OrderError) return { error: e.message };
517	      throw e;
518	    }
519	    redirect(`/dashboard/servers/${serverId}`);
520	  }
521	
522	  // RESERVE the first-month-free credit BEFORE opening the Checkout session. This is
523	  // the money-race fix: the card leg settles the discounted price up front, so unless
524	  // this account/IP's one credit is held EXCLUSIVELY here, two concurrent card
525	  // checkouts could each pass eligibility and each collect a free month from one
526	  // eligibility. The reserve's INSERT contends on the same two unique constraints as
527	  // the grant, so exactly one checkout holds it; a loser re-quotes at FULL price so
528	  // its stamped total, card leg and settlement all agree (displayed === charged). The
529	  // hold is CONFIRMED at fulfilment, RELEASED on `checkout.session.expired`, and
530	  // swept as a backstop — an abandoned checkout never permanently burns the offer.
531	  //
532	  // `promoCreditCents > 0` is the honest "this quote carries the free month" signal
533	  // (0 whenever the promo is off, already-redeemed via the re-quote above, or the
534	  // product is out of scope — firstMonthFreeAppliesTo). It is 0 for VPS today, so
535	  // this block is inert for VPS and correct the moment the owner extends the promo to
536	  // any card-checkout product.
537	  let promoReservationToken: string | null = null;
538	  if (quote.promoCreditCents > 0) {
539	    const reservedUntil = new Date(Date.now() + ORDER_CHECKOUT_EXPIRES_MS + RESERVATION_GRACE_MS);
540	    const res = await reserveFirstMonthFree({
541	      userId: user.id,
542	      ipHash: promoIpHash,
543	      serviceType: "VPS",
544	      campaign: promoCampaign,
545	      chargedCents: quote.chargeCents,
546	      reservedUntil,
547	    });
548	    if (res.reserved) {
549	      promoReservationToken = res.token;
550	    } else {
551	      // Lost the race (this account/IP already holds or redeemed the credit): re-quote
552	      // at FULL price and recompute the split so the card leg is the real full amount.
553	      quote = await orderQuote(intent, { suppressPromo: true });
554	      ({ walletApplied, cardCents } = walletSplit({ dueCents: dueWithTax(quote.chargeCents), balanceCents: user.balanceCents, useWallet }));
555	      // A full-price re-quote can be fully wallet-covered — provision immediately (its
556	      // own atomic claim inside placeOrder will correctly charge full on a lost claim).
557	      if (cardCents <= 0) {
558	        let serverId: string;
559	        try {
560	          serverId = await placeOrder(user, intent, null, { ipHash: promoIpHash, campaign: promoCampaign });
561	        } catch (e) {
562	          if (e instanceof OrderError) return { error: e.message };
563	          throw e;
564	        }
565	        redirect(`/dashboard/servers/${serverId}`);
566	      }
567	    }
568	  }
569	
570	  // RESERVE the checkout coupon BEFORE opening the Checkout session — the money-race fix
571	  // (Finding 1). The card leg settles the DISCOUNTED price up front, so unless this
572	  // account/IP's slot (the two @@unique constraints) AND a global-cap slot
573	  // (`timesRedeemed` vs `maxRedemptions`) are held EXCLUSIVELY here, N concurrent card
574	  // checkouts could each pass an advisory read and each collect the discount while only
575	  // ONE redemption is recorded — defeating one-per-person/IP AND maxRedemptions. The
576	  // reserve's atomic increment + guarded INSERT means exactly one checkout holds it; a
577	  // loser DROPS the coupon and re-quotes at FULL price so the stamped total, card leg and
578	  // settlement all agree (never a discounted leg without a backing hold — displayed ===
579	  // charged). The hold is CONFIRMED at fulfilment, RELEASED on `checkout.session.expired`,
580	  // and swept as a backstop, so an abandoned checkout never permanently burns the coupon.
581	  //
582	  // Reached only on the TRUE card path (cardCents > 0 at this point): the free-admin and
583	  // wallet-covers-the-total paths above provision immediately via placeOrder, whose OWN
584	  // atomic `claimOrderCoupon` handles the coupon — so a coupon is never both reserved here
585	  // and claimed there. `promoIpHash` is the same request IP the promo reserve used, already
586	  // null-normalised (an empty string would collide across every IP-less redemption).
587	  let checkoutIntent = intent;
588	  let couponReservationToken: string | null = null;
589	  if (quote.couponId && quote.couponDiscountCents > 0) {
590	    const reservedUntil = new Date(Date.now() + ORDER_CHECKOUT_EXPIRES_MS + RESERVATION_GRACE_MS);
591	    const res = await reserveOrderCoupon({
592	      couponId: quote.couponId,
593	      maxRedemptions: quote.couponMaxRedemptions,
594	      firstTimeOnly: quote.couponFirstTimeOnly,
595	      userId: user.id,
596	      ipHash: promoIpHash,
597	      amountCents: quote.couponDiscountCents,
598	      reservedUntil,
599	    });
600	    if (res.reserved) {
601	      couponReservationToken = res.token;
602	    } else {
603	      // Lost the exclusive hold: drop the coupon and re-quote at FULL price, then recompute
604	      // the split. Full price can only be >= the discounted one, so the card leg stays > 0
605	      // (no immediate-provision path to re-enter). Preserve the current promo state — keep a
606	      // promo hold if one was taken, otherwise suppress (promo off / ineligible / N/A here).
607	      checkoutIntent = { ...intent, couponCode: undefined };
608	      quote = await orderQuote(checkoutIntent, { suppressPromo: !promoReservationToken });
609	      ({ walletApplied, cardCents } = walletSplit({ dueCents: dueWithTax(quote.chargeCents), balanceCents: user.balanceCents, useWallet }));
610	    }
611	  }
612	
613	  // Card portion > 0 → charge ONLY the remainder on the card (not the full total).
614	  // On payment success the confirm route credits this card amount to the wallet and
615	  // then placeOrder debits the full chargeCents, so the wallet naturally absorbs
616	  // `walletApplied` and the card the rest — the wallet is never touched before the
617	  // card clears. (walletApplied is implied by cardCents vs. the recomputed charge,
618	  // so it needs no separate metadata field.)
619	  // The price is handed over EXPLICITLY, from the very quote the wallet split above
620	  // was computed from. Without this argument `createOrderCheckout` re-quotes
621	  // internally, microseconds later, from its own `new Date()` — the same function,
622	  // so no formula can drift, but two different instants. A promo boundary (or an
623	  // operator changing a plan price) falling between them would mean the card leg
624	  // and the stamped total were priced against two different worlds, and the wallet
625	  // would silently absorb the difference. One quote, one price, one charge.
626	  // If opening the session fails after we reserved, RELEASE both holds so the customer
627	  // never loses their offer (or the coupon's slot) to a checkout that never came into being.
628	  // `checkoutIntent` — not `intent` — so a coupon dropped on a lost reserve above is also
629	  // absent from the metadata fulfilment re-quotes from, matching the full-price `sold`.
630	  let url: string | null;
631	  try {
632	    url = await createOrderCheckout(
633	      user,
634	      cardCents,
635	      checkoutIntent,
636	      // Stamp the VAT the card leg was split from so fulfilment settles the SAME
637	      // tax-inclusive total — never re-derived after the card cleared.
638	      orderPriceOf(quote, { taxCents: taxOn(quote.chargeCents), ratePercent: taxCtx.ratePercent, country: taxCtx.country }),
639	      promoCampaign,
640	      promoReservationToken,
641	      couponReservationToken,
642	    );
643	  } catch (e) {
644	    if (promoReservationToken) await releaseReservation(promoReservationToken).catch(() => {});
645	    if (couponReservationToken) await releaseOrderCouponReservation(couponReservationToken).catch(() => {});
646	    throw e;
647	  }
648	  if (!url) {
649	    if (promoReservationToken) await releaseReservation(promoReservationToken).catch(() => {});
650	    if (couponReservationToken) await releaseOrderCouponReservation(couponReservationToken).catch(() => {});
651	    return { error: "Card payments aren't set up yet — top up your wallet to deploy." };
652	  }
653	  return { checkoutUrl: url };
654	}
