658	async function ownedServer(serverId: string) {
659	  const user = await requireUser();
660	  const server = await db.server.findUnique({ where: { id: serverId } });
661	  if (!server) throw new Error("Not found");
662	  if (server.userId !== user.id && user.role !== "ADMIN") throw new Error("Forbidden");
663	  return { user, server };
664	}
