666	export async function serverAction(serverId: string, action: string): Promise<{ error?: string } | void> {
667	  // Returns `{ error }` for anything the CUSTOMER can act on, so ServerControls
668	  // can render it — a `throw` here reaches the browser as Next's redacted generic
669	  // error, discarding the specific, actionable message (e.g. "Delete your data
670	  // volume(s) before reinstalling"). Only genuinely-impossible states still throw.
671	  const { user, server } = await ownedServer(serverId);
672	  const allowed: Record<string, "START" | "STOP" | "REBOOT" | "REINSTALL" | "DELETE"> = {
673	    start: "START",
674	    stop: "STOP",
675	    reboot: "REBOOT",
676	    reinstall: "REINSTALL",
677	    delete: "DELETE",
678	  };
679	  const type = allowed[action];
680	  if (!type) throw new Error("Invalid action"); // not reachable from the UI — a real bug if it happens
681	  if (server.status === "SUSPENDED" && user.role !== "ADMIN") {
682	    return { error: "This server is suspended. Settle the outstanding balance to control it again." };
683	  }
684	
685	  // A reinstall wipes the whole VM, including any block-storage volume the VM
686	  // owns (Proxmox `qm destroy --purge` frees every disk for that vmid).
687	  //
688	  // Count volumes by `serverId` ALONE, never by `status: "ATTACHED"`. Detaching
689	  // deliberately keeps `serverId` set so the volume can be re-attached
690	  // (worker/volumes.ts) — the disk stays owned by this vmid as an `unusedN`
691	  // entry, and PVE's destroy_vm frees unused disks too (include_unused => 1).
692	  // Filtering on ATTACHED therefore missed the worst case: customer fills a
693	  // volume, clicks Detach (the UI promises "Data is preserved."), clicks
694	  // Reinstall — both guards see zero attached volumes, and the purge takes the
695	  // data with it. `reinstallToOs` in actions-server-lifecycle.ts always counted
696	  // by serverId; this path did not. That asymmetry was the bug.
697	  if (type === "REINSTALL") {
698	    const pinnedVolumes = await db.volume.count({ where: { serverId } });
699	    if (pinnedVolumes > 0) {
700	      return {
701	        error:
702	          "Delete your data volume(s) before reinstalling — a reinstall wipes the whole server, and that includes detached volumes still assigned to it. Open Volumes first.",
703	      };
704	    }
705	  }
706	
707	  const pending = await db.job.count({
708	    where: { serverId, status: { in: ["QUEUED", "RUNNING"] } },
709	  });
710	  // Was a silent `return`: the customer clicked Start and nothing happened, ever,
711	  // with no explanation. Tell them why.
712	  if (pending > 0) return { error: "Another operation is already running on this server. Wait for it to finish." };
713	
714	  if (type === "DELETE") {
715	    await db.server.update({ where: { id: serverId }, data: { status: "DELETING" } });
716	  }
717	  await db.job.create({ data: { type, serverId } });
718	  await audit(user.id, `server.${action}`, serverId);
719	  if (type === "DELETE") redirect(user.role === "ADMIN" ? "/admin/servers" : "/dashboard");
720	  revalidatePath(`/dashboard/servers/${serverId}`);
721	}
