723	// ---------- Wallet (demo top-up until a payment gateway is connected) ----------
724	
725	export async function topUp(prev: any, formData: FormData): Promise<{ error?: string }> {
726	  const user = await requireUser();
727	  // Spend/credit path: block while impersonating so an admin can't mint or move
728	  // a customer's balance on their behalf.
729	  await assertNotImpersonating();
730	  // Security: never mint free wallet balance in production. The demo gateway that
731	  // credits without a real payment is only ever acceptable in non-production, and
732	  // is refused outright when NODE_ENV === "production" regardless of Stripe.
733	  if (process.env.NODE_ENV === "production") {
734	    return { error: "Please add funds with a card via the secure checkout." };
735	  }
736	  // Once Stripe is configured, the demo gateway is hard-disabled — top-ups must
737	  // go through Checkout.
738	  const { stripeConfigured } = await import("./stripe");
739	  if (stripeConfigured()) {
740	    return { error: "Please add funds with a card via the secure checkout." };
741	  }
742	  // Throttle demo top-ups per user+IP to prevent rapid free-credit minting.
743	  const topupIp = clientIp(await headers());
744	  const topupRl = checkRateLimit(`topup:${user.id}:${topupIp}`, { max: 10, windowMs: 60 * 60 * 1000 });
745	  if (!topupRl.ok) {
746	    return { error: `Too many top-up attempts. Try again in ${topupRl.retryAfterSec}s.` };
747	  }
748	  const amount = Number(formData.get("amount"));
749	  if (!Number.isFinite(amount) || amount < 1 || amount > 1000) {
750	    return { error: "Amount must be between $1 and $1000." };
751	  }
752	  const cents = Math.round(amount * 100);
753	  // Enforce the admin-configured minimum top-up (`min_topup_cents`, default 500).
754	  const minTopup = await getSettingInt("min_topup_cents", 500);
755	  if (cents < minTopup) {
756	    return { error: `Minimum top-up is $${(minTopup / 100).toFixed(2)}.` };
757	  }
758	
759	  // Optional promo code: applied via the COUPON_COOKIE the billing CouponField
760	  // sets. applyCouponToTopup re-validates for this user against the real amount.
761	  const jar = await cookies();
762	  const couponCode = jar.get(COUPON_COOKIE)?.value?.trim();
763	  let bonusCents = 0;
764	  let couponId: string | null = null;
765	  let couponLabel = "";
766	  if (couponCode) {
767	    const result = await applyCouponToTopup(couponCode, cents);
768	    if (result.ok) {
769	      bonusCents = result.bonusCents;
770	      couponId = result.couponId;
771	      couponLabel = result.label;
772	    } else {
773	      // REFUSE, don't silently drop. The old code fell through and completed the
774	      // top-up with no bonus and no message, so a code that passed validation at
775	      // the preview amount but fails against the real one (a `minAmountCents`
776	      // floor, an exhausted limit, an expiry) simply vanished — the customer paid
777	      // expecting a bonus and got nothing, with nowhere to look. Nothing has been
778	      // charged at this point, so stopping is free and the customer can retry
779	      // without the code or with a larger amount.
780	      return {
781	        error:
782	          `${result.error ?? "That promo code can't be applied to this amount."} ` +
783	          `Nothing has been charged — adjust the amount or remove the code and try again.`,
784	      };
785	    }
786	  }
787	
788	  try {
789	    await db.$transaction(async (tx) => {
790	      // Claim the coupon FIRST, atomically. The old code did an unconditional
791	      // `coupon.update({ timesRedeemed: { increment: 1 } })` after a plain read of
792	      // the cap in the preview, so two top-ups racing for the last slot both saw
793	      // room and both incremented — the limit could be blown past by any number of
794	      // concurrent claims. Mirror `claimOrderCoupon`: a conditional `updateMany`
795	      // gated on `timesRedeemed < max` is the only thing that atomically hands out
796	      // the final slot, and the unique(coupon,user) create fails a double-claim.
797	      if (bonusCents > 0 && couponId) {
798	        const c = await tx.coupon.findUnique({ where: { id: couponId }, select: { maxRedemptions: true } });
799	        const claim = await tx.coupon.updateMany({
800	          where:
801	            c?.maxRedemptions == null
802	              ? { id: couponId, active: true }
803	              : { id: couponId, active: true, timesRedeemed: { lt: c.maxRedemptions } },
804	          data: { timesRedeemed: { increment: 1 } },
805	        });
806	        if (claim.count !== 1) throw new CouponClaimError("That code has just reached its redemption limit.");
807	        try {
808	          await tx.couponRedemption.create({
809	            data: { couponId, userId: user.id, amountCents: bonusCents, context: "topup" },
810	          });
811	        } catch {
812	          throw new CouponClaimError("You’ve already used this code.");
813	        }
814	      }
815	      await tx.user.update({
816	        where: { id: user.id },
817	        data: { balanceCents: { increment: cents + bonusCents } },
818	      });
819	      await tx.walletTransaction.create({
820	        data: { userId: user.id, amountCents: cents, description: "Wallet top-up (demo gateway)" },
821	      });
822	      if (bonusCents > 0 && couponId) {
823	        await tx.walletTransaction.create({
824	          data: {
825	            userId: user.id,
826	            amountCents: bonusCents,
827	            description: `Promo ${couponCode!.toUpperCase()} — ${couponLabel}`,
828	          },
829	        });
830	      }
831	    });
832	  } catch (e) {
833	    // The demo gateway charges nothing external, so a rolled-back transaction
834	    // means the customer is untouched — safe to surface and let them retry.
835	    if (e instanceof CouponClaimError) {
836	      return { error: `${e.message} Nothing has been charged — remove the code and try again.` };
837	    }
838	    throw e;
839	  }
840	  jar.delete(COUPON_COOKIE);
841	  await audit(user.id, "wallet.topup", `$${amount}${bonusCents > 0 ? ` +bonus $${(bonusCents / 100).toFixed(2)}` : ""}`);
842	  // First successful paid action may unlock a referral reward for both parties.
843	  try {
844	    await maybeRewardReferral(user.id);
845	  } catch { /* non-fatal */ }
846	  revalidatePath("/dashboard/billing");
847	  return {};
848	}
