863	export async function renewNow(serverId: string): Promise<{ error?: string } | void> {
864	  // Spend path: block wallet debits while an admin is impersonating.
865	  await assertNotImpersonating();
866	  const { user, server } = await ownedServer(serverId);
867	  if (server.isFree || !server.expiresAt) return;
868	  // A MANUAL renewal is a fresh purchase decision, so it is gated. Note this
869	  // cannot strand an existing customer: every account that owns a server today
870	  // predates verification and is grandfathered, and the automatic renewal in
871	  // worker/billing.ts does not pass through here at all — nobody's server lapses
872	  // because of this check.
873	  const unverified = await emailVerificationError(user);
874	  if (unverified) return { error: unverified };
875	  const plan = await db.plan.findUnique({ where: { id: server.planId } });
876	  if (!plan) return;
877	  // A game server carries BOTH a base `planId` and a `gamePlanId`, and it is sold
878	  // at the game plan's FLAT price. Reading only `plan.priceCents` here charged a
879	  // game-server owner the base VPS term price instead — `minecraft-mm8w85` sold at
880	  // $4.99 on a Starter base plan would have been billed $8.99, an 80% overcharge.
881	  const gamePlan = server.gamePlanId
882	    ? await db.gamePlan.findUnique({
883	        where: { id: server.gamePlanId },
884	        select: { name: true, priceCents: true, termMonths: true },
885	      })
886	    : null;
887	  // Charge the IP surcharge based on the ACTUAL allocated IP (matching worker/
888	  // billing.ts), not the intent flag — a NAT-fallback server never gets billed.
889	  const hasDedicatedIp = !!(await db.dedicatedIp.findFirst({
890	    where: { serverId }, select: { id: true },
891	  }));
892	  // The SERVER OWNER (not necessarily the acting user) determines the VAT/GST rate
893	  // and the spend cap — resolved up front so `renewalQuote` prices tax-inclusive.
894	  const owner = await db.user.findUnique({ where: { id: server.userId } });
895	  if (!owner) return;
896	  const renewTaxCtx = await taxContextForUser(owner);
897	  // Priced through `renewalCharge` — the SAME function the automatic renewal sweep
898	  // in worker/billing.ts and the saved-card path use. Not a second copy of the
899	  // arithmetic: see lib/renewal-quote.ts for both incidents that produced this
900	  // rule, the second of which was a fresh duplicate written hours after the first.
901	  const quote = renewalQuote(
902	    {
903	      termMonths: server.termMonths,
904	      extraDiskGB: server.extraDiskGB,
