1046	  if (!serverId || !Number.isFinite(days) || days === 0 || Math.abs(days) > 365) {
1047	    return { error: "Days must be between -365 and 365." };
1048	  }
1049	  const server = await db.server.findUnique({ where: { id: serverId } });
1050	  if (!server) return { error: "Server not found." };
1051	  const base = server.expiresAt ? server.expiresAt.getTime() : Date.now();
1052	
1053	  // ─── EXPIRESAT INTEGRITY ────────────────────────────────────────────────────
1054	  // The whole proration model rests on "every month between now and `expiresAt` is
1055	  // a month the customer has actually bought" (see lib/proration.ts
1056	  // remainingMonths). This action moves `expiresAt` by up to a year per call, with
1057	  // no call limit and no payment — so before the persisted rate existed, an admin
1058	  // goodwill gift of 12 months was directly convertible to cash: downgrade the
1059	  // gifted server and the prorated credit paid out real wallet money for months
1060	  // nobody had ever been charged for. Admin-only, so never a self-service exploit,
1061	  // but a support agent clicking "extend" was minting refundable balance.
1062	  //
1063	  // SEMANTICS CHOSEN: gifted months are recorded as sold at 100% off, and blended
1064	  // into the rate the existing months are on. That is the honest reading of a gift
1065	  // — those months cost the customer nothing, so nothing may prorate out of them —
1066	  // and it is exact rather than blunt: the blend leaves the CASH VALUE of the
1067	  // remaining window completely unchanged, so a customer who paid for 12 months and
1068	  // was gifted a 13th still gets back precisely what those 12 paid months are worth
1069	  // on a downgrade. Zeroing the whole term instead would confiscate what they paid;
1070	  // leaving the rate alone is the money printer. Repeated gifts only ever dilute
1071	  // toward 100, so no number of calls can raise the payout.
