1081	        currentMonths: remainingMonths(server.expiresAt, Date.now()),
1082	        addedPercent: 100, // gifted: no cash changed hands for these months
1083	        addedMonths: (days * 86400_000) / MS_PER_AVG_MONTH,
1084	      })
1085	    : resolveTermPromoPercent(server.termPromoPercent);
