67	// Strip path separators, quotes and control chars so the filename can't break
68	// out of the Content-Disposition header.
69	function sanitizeFilename(name?: string): string {
70	  if (!name) return "";
71	  const cleaned = Array.from(name)
72	    .filter((ch) => {
73	      const c = ch.codePointAt(0) ?? 0;
74	      if (c < 0x20 || c === 0x7f) return false; // control chars
75	      if (ch === '"' || ch === "\\" || ch === "/") return false;
76	      return true;
77	    })
78	    .join("");
79	  return cleaned.trim().slice(0, 200);
80	}
